def make_adj_words():
    words = []
    subs = ["adj_qualities", "adj_colors", "adj_size_time", "adj_sensory", "adj_personality"]
    for i, w in enumerate(adj_data):
        sub = subs[i // 50]
        words.append((w[0], w[1], w[2], f"[{w[0].lower()}]", w[3], w[4], w[5], w[6], "adjectives", sub, w[7]))
    return words

